def solve():
    na = 2000
    nb = 2016
    d = 1000

    max_k = 0

    # Let's try A as a consecutive range of length na.
    # A = {x, x+1, ..., x+na-1}
    # B = {y, y+1, ..., y+nb-1}
    # This is what we did before. Let's try different s = y-x.
    for s in range(-nb, nb + na):
        k = 0
        for i in range(na):
            lower = max(0, i - s - d)
            upper = min(nb - 1, i - s + d)
            if lower <= upper:
                k += (upper - lower + 1)
        if k > max_k:
            max_k = k

    print(f"Max K for consecutive A, B: {max_k}")

solve()

def solve_best_A_centered():
    na = 2000
    nb = 2016
    d = 1000

    # B = {1, 2, ..., 2016}
    # A = {x, x+1, ..., x+na-1}
    # We want to find x that maximizes K.
    max_k = 0
    best_x = 0
    for x in range(-1000, 3000):
        k = 0
        for i in range(x, x + na):
            lower = max(1, i - d)
            upper = min(nb, i + d)
            if lower <= upper:
                k += (upper - lower + 1)
        if k > max_k:
            max_k = k
            best_x = x
    print(f"Max K: {max_k}, Best x: {best_x}")

solve_best_A_centered()

