def solve_all_B_subsets():
    na = 2000
    nb = 2016
    nc = 2020
    d = 1000

    max_k = 0
    for start in range(1, 6):
        # B is a consecutive range of length 2016 in {1, ..., 2020}
        # B = {start, ..., start + 2016 - 1}
        # B_range is {start, ..., start + 2015}
        # Actually, start + 2015 must be <= 2020, so start <= 2020 - 2015 = 5.
        # So start can be 1, 2, 3, 4, 5.
        B_range = range(start, start + nb)
        c = []
        for m in range(1, nc + 1):
            lower = max(start, m - d)
            upper = min(start + nb - 1, m + d)
            if lower <= upper:
                c.append(upper - lower + 1)
            else:
                c.append(0)
        c.sort(reverse=True)
        k = sum(c[:na])
        print(f"B = {B_range}, K = {k}")
        if k > max_k:
            max_k = k
    print(f"Overall Max K: {max_k}")

solve_all_B_subsets()
